package com.skyfish924.treasury.content;import com.mojang.serialization.Codec;import com.skyfish924.treasury.AllItems;import net.minecraft.advancements.critereon.ContextAwarePredicate;import net.minecraft.advancements.critereon.SimpleCriterionTrigger;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.ItemStack;import org.jetbrains.annotations.NotNull;import java.util.Optional;public class TeenyWeenyClass extends SimpleCriterionTrigger<TeenyWeenyClass.Instance> { public void trigger(ServerPlayer player) {int count = player.getInventory().items.stream().filter(stack -> stack.is(AllItems.ONE_HUNDRED_DOLLAR_BILL.get())).mapToInt(ItemStack::getCount).sum();if (count >= 2304) {trigger(player, instance -> true);}}@Override public @NotNull Codec<Instance> codec() {return Instance.CODEC;}public record Instance(Optional<ContextAwarePredicate> player) implements SimpleCriterionTrigger.SimpleInstance { public static final Codec<Instance> CODEC = ContextAwarePredicate.CODEC.optionalFieldOf("player").xmap(Instance::new, Instance::player).codec();}}